    {
      "name": "one_le_pow_mul_abs_eval_div",
      "module_name": "Mathlib.Algebra.Polynomial.DenomsClearable",
      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : Field K] [inst_1 : LinearOrder K] [IsStrictOrderedRing K] {f : Polynomial ℤ} {a b : ℤ},\n  0 < b →\n    Polynomial.eval (↑a / ↑b) (Polynomial.map (algebraMap ℤ K) f) ≠ 0 →\n      1 ≤ ↑b ^ f.natDegree * |Polynomial.eval (↑a / ↑b) (Polynomial.map (algebraMap ℤ K) f)|"
    },
    {
      "name": "MvPolynomial.schwartz_zippel_sup_sum",
      "module_name": "Mathlib.Algebra.MvPolynomial.SchwartzZippel",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] [IsDomain R] [inst_2 : DecidableEq R] {n : ℕ} {p : MvPolynomial (Fin n) R},\n  p ≠ 0 →\n    ∀ (S : Fin n → Finset R),\n      ↑{x ∈ Fintype.piFinset fun i => S i | (MvPolynomial.eval x) p = 0}.card / ∏ i, ↑(S i).card ≤\n        p.support.sup fun s => ∑ i, ↑(s i) / ↑(S i).card"
    },
    {
      "name": "addRothNumber",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Defs",
      "kind": "definition",
      "type": "{α : Type u_2} → [DecidableEq α] → [AddMonoid α] → Finset α →o ℕ"
    },
    {
      "name": "addRothNumber_le",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} [inst : DecidableEq α] [inst_1 : AddMonoid α] (s : Finset α), addRothNumber s ≤ s.card"
    },
    {
      "name": "PrimeSpectrum.ConstructibleSetData.degBound",
      "module_name": "Mathlib.RingTheory.Spectrum.Prime.ConstructibleSet",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : CommSemiring R] → PrimeSpectrum.ConstructibleSetData (Polynomial R) → ℕ"
    }
  ]
}

