{
  "items": [
    {
      "name": "le_ciSup_set",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Indexed",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : ConditionallyCompleteLattice α] {f : β → α} {s : Set β},\n  BddAbove (f '' s) → ∀ {c : β}, c ∈ s → f c ≤ ⨆ i, f ↑i"
    },
    {
      "name": "csSup_image",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Indexed",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : ConditionallyCompleteLattice α] [Nonempty β] {s : Set β},\n  s.Nonempty → ∀ {f : β → α}, BddAbove (Set.range fun i => f ↑i) → sSup ∅ ≤ ⨆ i, f ↑i → sSup (f '' s) = ⨆ a ∈ s, f a"
    },
    {
      "name": "le_ciSup_of_le",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Indexed",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {ι : Sort u_4} [inst : ConditionallyCompleteLattice α] {a : α} {f : ι → α},\n  BddAbove (Set.range f) → ∀ (c : ι), a ≤ f c → a ≤ iSup f"
    },
    {
      "name": "isLUB_ciSup_set",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Indexed",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : ConditionallyCompleteLattice α] {f : β → α} {s : Set β},\n  BddAbove (f '' s) → s.Nonempty → IsLUB (f '' s) (⨆ i, f ↑i)"
    },
    {
      "name": "ciSup_image",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Indexed",
      "kind": "theorem",
      "type": "∀ {α : Type u_5} {ι : Type u_6} {ι' : Type u_7} [inst : ConditionallyCompleteLattice α] [Nonempty ι] [Nonempty ι']\n  {s : Set ι},\n  s.Nonempty →\n    ∀ {f : ι → ι'} {g : ι' → α},\n      BddAbove (Set.range fun i => g (f ↑i)) → sSup ∅ ≤ ⨆ i, g (f ↑i) → ⨆ i ∈ f '' s, g i = ⨆ x ∈ s, g (f x)"
    }
  ]
}
